def check_valid_string(s: str) -> bool:
    low = high = 0   # loosest/tightest plausible open counts
    for ch in s:
        if ch == '(':
            low += 1
            high += 1
        elif ch == ')':
            high -= 1
            low = max(low - 1, 0)
        else:  # '*'
            high += 1        # treat as '('
            low = max(low - 1, 0)  # or as ')'
        if high < 0:
            return False
    return low == 0

