#include <bits/stdc++.h>
using namespace std;

bool checkValidString(string s) {
    int low = 0, high = 0;
    for (char ch : s) {
        if (ch == '(') { ++low; ++high; }
        else if (ch == ')') { --high; low = max(low - 1, 0); }
        else { ++high; low = max(low - 1, 0); }
        if (high < 0) return false;
    }
    return low == 0;
}

